var hasard=(a,b)=>a+Math.floor(Math.random()*(b-a+1)),prendre=a=>a[Math.floor(Math.random()*a.length)],melanger=a=>{for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};function qcm(bonne,reserve,n){let autres=melanger([...new Set(reserve)].filter(r=>r!==bonne)).slice(0,(n||4)-1),choix=melanger([bonne,...autres]);return{type:"qcm",choix,reponse:choix.indexOf(bonne)}}var fr=(v,d)=>String(Math.round(v*Math.pow(10,d))/Math.pow(10,d)).replace(".",","),tex=(v,d)=>fr(v,d??3).replace(",","{,}"),num=(v,d,rel)=>({type:"nombre",reponse:fr(v,d),tolerance:Math.max(Math.abs(v)*(rel||.03),.5*Math.pow(10,-d))});export{hasard,prendre,melanger,qcm,fr,tex,num};
